declare module '*.vue' {
  import type { DefineComponent } from 'vue';
  const component: DefineComponent<Record<string, unknown>, Record<string, unknown>, unknown>;
  export default component;
}

export interface Signup { id: string; eventId: string; seats: number; state: 'BOOKED' | 'WAITING' | 'CANCELLED'; }

/** 活动报名采用独立名额口径：候补不占正式席位。 */
export function availabilityFor(capacity: number, eventId: string, signups: Signup[]): number {
  const used = signups.filter((row) => row.eventId === eventId && row.state === 'BOOKED')
    .reduce((sum, row) => sum + row.seats, 0);
  return Math.max(0, capacity - used);
}

import { availabilityFor, type Signup } from './availability';

export interface EventDefinition { id: string; title: string; capacity: number; }

export function previewSignup(event: EventDefinition, seats: number, signups: Signup[]) {
  if (!Number.isSafeInteger(seats) || seats < 1) return { allowed: false, reason: '席位数量无效', remaining: 0 };
  const remaining = availabilityFor(event.capacity, event.id, signups);
  return { allowed: seats <= remaining, reason: seats <= remaining ? '' : '可进入候补名单', remaining };
}

export function eventCountSummary(eventId: string, signups: Signup[]) {
  const selected = signups.filter((row) => row.eventId === eventId);
  return {
    booked: selected.filter((row) => row.state === 'BOOKED').reduce((sum, row) => sum + row.seats, 0),
    waiting: selected.filter((row) => row.state === 'WAITING').reduce((sum, row) => sum + row.seats, 0),
  };
}

export interface LegacyBorrowRow { deviceCode: string; pieces: number; closed: boolean; }

/** 退役工作台的旧口径，只供旧记录回看；没有地点维度。 */
export function availabilityFor(total: number, deviceCode: string, rows: LegacyBorrowRow[]): number {
  return Math.max(0, total - rows.filter((row) => row.deviceCode === deviceCode && !row.closed)
    .reduce((sum, row) => sum + row.pieces, 0));
}

export function legacySummary(rows: LegacyBorrowRow[]): string {
  const open = rows.filter((row) => !row.closed);
  return `旧台账未结 ${open.length} 单，共 ${open.reduce((sum, row) => sum + row.pieces, 0)} 件`;
}

